from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    h, w = len(grid), len(grid[0])
    for top in range(h - 2):
        for left in range(w - 2):
            color = grid[top][left]
            if color == background:
                continue
            for bottom in range(top + 2, h):
                for right in range(left + 2, w):
                    if bottom - top != right - left:
                        continue
                    if any(grid[r][c] != background for r in range(top + 1, bottom) for c in range(left + 1, right)):
                        continue
                    sides = [
                        all(grid[top][c] == color for c in range(left, right + 1)),
                        all(grid[bottom][c] == color for c in range(left, right + 1)),
                        all(grid[r][left] == color for r in range(top, bottom + 1)),
                        all(grid[r][right] == color for r in range(top, bottom + 1)),
                    ]
                    # A missing side leaves its corner cells supplied by the adjacent sides.
                    open_sides = [
                        all(grid[top][c] == background for c in range(left + 1, right)),
                        all(grid[bottom][c] == background for c in range(left + 1, right)),
                        all(grid[r][left] == background for r in range(top + 1, bottom)),
                        all(grid[r][right] == background for r in range(top + 1, bottom)),
                    ]
                    if sum(sides) == 4 or (sum(sides) == 3 and sum(open_sides) >= 1):
                        fill = 7 if (bottom - top - 1) % 2 == 1 else 2
                        for r in range(top + 1, bottom):
                            for c in range(left + 1, right):
                                out[r][c] = fill
    # One-cell gaps in an open-sided U are also filled (the demo includes a 3-sided notch).
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] != background:
                continue
            neighbors = [grid[r - 1][c], grid[r + 1][c], grid[r][c - 1], grid[r][c + 1]]
            for color in set(neighbors) - {background}:
                if neighbors.count(color) >= 3:
                    out[r][c] = 7
                    break
    return out

